			startCursor: 0,
			wantCursor:  29,
		},
		{
			name:        "G",
			key:         tea.KeyPressMsg{Code: 'G', Text: "G"},
			startCursor: 0,
			wantCursor:  29,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			ss := statusStyles{colorEnabled: false, width: 100}
